import csv
import json
import urllib.request
from datetime import datetime
from pathlib import Path

STATIONS_PATH = Path('/root/data/michigan_stations.txt')
OUTPUT_PATH = Path('/root/output/flood_results.csv')

START_DATE = '2025-04-01'
END_DATE = '2025-04-07'
PARAM = '00060'  # discharge

# Fetch daily stats (p95) for a station

def fetch_p95_by_day(site_no: str):
    url = (
        'https://waterservices.usgs.gov/nwis/stat/'
        f'?format=rdb&sites={site_no}&parameterCd={PARAM}'
    )
    with urllib.request.urlopen(url) as resp:
        text = resp.read().decode('utf-8')
    lines = [ln for ln in text.splitlines() if ln and not ln.startswith('#')]
    if not lines:
        return {}
    header = lines[0].split('\t')
    data_lines = lines[2:] if len(lines) > 2 and lines[1].startswith(('5s','10s','15s','20s','3n','6n','8n','12s','12n','1s')) else lines[1:]
    idx = {name: i for i, name in enumerate(header)}
    required = ['month_nu', 'day_nu', 'p95_va']
    if not all(k in idx for k in required):
        return {}
    p95_by_day = {}
    for ln in data_lines:
        parts = ln.split('\t')
        if len(parts) <= max(idx.values()):
            continue
        try:
            month = int(parts[idx['month_nu']])
            day = int(parts[idx['day_nu']])
            p95_raw = parts[idx['p95_va']]
            if p95_raw == '' or p95_raw is None:
                continue
            p95 = float(p95_raw)
            p95_by_day[(month, day)] = p95
        except (ValueError, TypeError):
            continue
    return p95_by_day


def fetch_daily_values(site_no: str):
    url = (
        'https://waterservices.usgs.gov/nwis/dv/'
        f'?format=json&sites={site_no}&parameterCd={PARAM}'
        f'&startDT={START_DATE}&endDT={END_DATE}'
    )
    with urllib.request.urlopen(url) as resp:
        data = json.load(resp)
    series = data.get('value', {}).get('timeSeries', [])
    if not series:
        return []
    # Expect one series for this parameter
    values = series[0].get('values', [])
    if not values:
        return []
    return values[0].get('value', [])


stations = [ln.strip() for ln in STATIONS_PATH.read_text().splitlines() if ln.strip()]
results = []

for site_no in stations:
    try:
        p95_by_day = fetch_p95_by_day(site_no)
        if not p95_by_day:
            continue
        daily_values = fetch_daily_values(site_no)
        flood_days = 0
        for item in daily_values:
            date_str = item.get('dateTime', '')[:10]
            if not date_str:
                continue
            try:
                dt = datetime.strptime(date_str, '%Y-%m-%d')
            except ValueError:
                continue
            key = (dt.month, dt.day)
            if key not in p95_by_day:
                continue
            val_raw = item.get('value')
            try:
                val = float(val_raw)
            except (TypeError, ValueError):
                continue
            if val >= p95_by_day[key]:
                flood_days += 1
        if flood_days > 0:
            results.append((site_no, flood_days))
    except Exception as e:
        # Skip stations with errors to keep processing going
        continue

OUTPUT_PATH.parent.mkdir(parents=True, exist_ok=True)
with OUTPUT_PATH.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for site_no, flood_days in results:
        writer.writerow([site_no, flood_days])

print(f"Wrote {len(results)} stations to {OUTPUT_PATH}")
PY"}

